-- ============================================================
-- 20260710140000_whatsapp_logs.sql
-- ============================================================
-- Tracks every WhatsApp message the app attempts to send (invoice copy,
-- due-date reminder, etc.) so there is a complete, queryable monitoring
-- trail: who was messaged, when, about what, and whether it succeeded.
-- The actual sending happens through whichever webhook is configured in
-- Settings -> WhatsApp; this table just records the outcome.

CREATE TABLE public.whatsapp_logs (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  customer_id UUID REFERENCES public.customers(id) ON DELETE SET NULL,
  customer_name TEXT,
  whatsapp_number TEXT NOT NULL,
  message_type TEXT NOT NULL DEFAULT 'invoice' CHECK (message_type IN ('invoice', 'due_reminder', 'order_status', 'other')),
  reference_id UUID,
  reference_number TEXT,
  message_text TEXT,
  status TEXT NOT NULL DEFAULT 'pending' CHECK (status IN ('pending', 'sent', 'failed')),
  error_message TEXT,
  created_by UUID,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
ALTER TABLE public.whatsapp_logs ENABLE ROW LEVEL SECURITY;
GRANT SELECT, INSERT, UPDATE, DELETE ON public.whatsapp_logs TO authenticated;
GRANT ALL ON public.whatsapp_logs TO service_role;

CREATE POLICY "Staff can view whatsapp_logs" ON public.whatsapp_logs FOR SELECT TO authenticated USING (public.is_staff(auth.uid()));
CREATE POLICY "Staff can insert whatsapp_logs" ON public.whatsapp_logs FOR INSERT TO authenticated WITH CHECK (public.is_staff(auth.uid()));
CREATE POLICY "Staff can update whatsapp_logs" ON public.whatsapp_logs FOR UPDATE TO authenticated USING (public.is_staff(auth.uid())) WITH CHECK (public.is_staff(auth.uid()));
CREATE POLICY "Admins and managers can delete whatsapp_logs" ON public.whatsapp_logs FOR DELETE TO authenticated USING (public.has_role(auth.uid(), 'admin') OR public.has_role(auth.uid(), 'manager'));

-- ============================================================
-- 20260710150000_invoice_terms_attachments_commission.sql
-- ============================================================
-- Fixes 4 confirmed workflow bugs on the invoice creation screen where
-- the UI existed but nothing was actually persisted:
--   1. Terms & Condition typed per-invoice was discarded on save
--   2. Attached files only existed as temporary blob: URLs
--   3. Commission set on an invoice never created a commissions record
--   4. An initial payment taken during invoice creation never created a
--      real payments record

ALTER TABLE public.invoices
  ADD COLUMN terms TEXT,
  ADD COLUMN attachments JSONB NOT NULL DEFAULT '[]'::jsonb,
  ADD COLUMN commission_pct NUMERIC NOT NULL DEFAULT 0,
  ADD COLUMN commission_agent TEXT;

-- Storage bucket for invoice attachments (private; the app signs URLs on
-- demand for authenticated staff, matching every other table's RLS style).
INSERT INTO storage.buckets (id, name, public)
VALUES ('invoice-attachments', 'invoice-attachments', false)
ON CONFLICT (id) DO NOTHING;

CREATE POLICY "Staff can read invoice attachments"
ON storage.objects FOR SELECT TO authenticated
USING (bucket_id = 'invoice-attachments' AND public.is_staff(auth.uid()));

CREATE POLICY "Staff can upload invoice attachments"
ON storage.objects FOR INSERT TO authenticated
WITH CHECK (bucket_id = 'invoice-attachments' AND public.is_staff(auth.uid()));

CREATE POLICY "Staff can delete invoice attachments"
ON storage.objects FOR DELETE TO authenticated
USING (bucket_id = 'invoice-attachments' AND public.is_staff(auth.uid()));

-- ============================================================
-- 20260716120000_customer_credit_bank_fields.sql
-- ============================================================
-- Fields confirmed present in the reference app's Add Client/Supplier
-- screen but missing from ours: credit limit, payment terms, an
-- explicit opening balance + date (separate from the running balance,
-- which grows from invoices/payments), and a per-client bank info block
-- (useful for suppliers you pay, or clients who pay you by bank transfer).

ALTER TABLE public.customers
  ADD COLUMN max_credit_limit NUMERIC,
  ADD COLUMN payment_terms TEXT DEFAULT 'No Due Date',
  ADD COLUMN opening_balance NUMERIC NOT NULL DEFAULT 0,
  ADD COLUMN opening_date DATE NOT NULL DEFAULT CURRENT_DATE,
  ADD COLUMN bank_name TEXT,
  ADD COLUMN payable_to TEXT,
  ADD COLUMN bank_account_no TEXT,
  ADD COLUMN ifsc_code TEXT,
  ADD COLUMN upi_id TEXT;

-- ============================================================
-- 20260716170000_invoice_shipping_address.sql
-- ============================================================
-- The invoice creation screen has a "Ship To" / "Edit Address" action, but
-- it only ever set local component state via a native prompt() — nothing
-- was ever saved, so it silently reset every time you reopened the
-- invoice. Give it a real column.
ALTER TABLE public.invoices ADD COLUMN shipping_address TEXT;

